package com.jimliddle.pocketdocs;

import static org.junit.Assert.*;
import static org.junit.Assume.*;

import android.content.*;
import android.net.Uri;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import org.json.*;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.robolectric.*;
import org.robolectric.annotation.Config;

/** Uses actual model vectors generated by test-retrieval.py, through SQLite and MCP. */
@RunWith(RobolectricTestRunner.class)
@Config(sdk = 28, manifest = Config.NONE)
public class PaperRetrievalTest {
  @Test
  public void realModelEvidenceSurvivesSqliteAndMcp() throws Exception {
    InputStream input = getClass().getResourceAsStream("/paper.json");
    // Standalone unit tests can run without network. CI generates this fixture first.
    assumeNotNull(input);
    JSONObject fixture;
    try (InputStream in = input) {
      fixture = new JSONObject(new String(in.readAllBytes(), StandardCharsets.UTF_8));
    }
    JSONObject vectors = fixture.getJSONObject("vectors");
    Context context = RuntimeEnvironment.getApplication();
    context.deleteDatabase("documents.db");
    String root = "content://paper/tree/test";
    context
        .getContentResolver()
        .takePersistableUriPermission(Uri.parse(root), Intent.FLAG_GRANT_READ_URI_PERMISSION);
    try (Store store =
        new Store(
            context,
            new EmbeddingProvider() {
              public String error() {
                return "";
              }

              public float[] embed(String text) {
                try {
                  JSONArray a = vectors.getJSONArray(text);
                  float[] v = new float[a.length()];
                  for (int i = 0; i < v.length; i++) v[i] = (float) a.getDouble(i);
                  return v;
                } catch (JSONException e) {
                  throw new AssertionError("Missing real model fixture vector", e);
                }
              }
            })) {
      store.addRoot(root, "Paper");
      List<Store.Passage> passages = new ArrayList<>();
      JSONArray source = fixture.getJSONArray("passages");
      for (int i = 0; i < source.length(); i++) {
        JSONObject p = source.getJSONObject(i);
        passages.add(
            new Store.Passage(
                "paper",
                "1706.03762.pdf",
                p.getInt("page"),
                p.getInt("chunk"),
                p.getString("text")));
      }
      store.replaceRoot(root, store.roots().get(0)[4], passages, "OK");
      McpEngine engine = new McpEngine(store, () -> false);
      McpEngine readableEngine = new McpEngine(store);
      JSONArray cases = fixture.getJSONArray("cases");
      for (int i = 0; i < cases.length(); i++) {
        JSONObject test = cases.getJSONObject(i);
        JSONObject request =
            new JSONObject()
                .put("jsonrpc", "2.0")
                .put("id", i)
                .put("method", "tools/call")
                .put(
                    "params",
                    new JSONObject()
                        .put("name", "search_documents")
                        .put("arguments", new JSONObject().put("query", test.getString("query"))));
        JSONObject response =
            new JSONObject(
                engine
                    .handle(request)
                    .getJSONObject("result")
                    .getJSONArray("content")
                    .getJSONObject(0)
                    .getString("text"));
        JSONArray out = response.getJSONArray("passages");
        String readable =
            readableEngine
                .handle(request)
                .getJSONObject("result")
                .getJSONArray("content")
                .getJSONObject(0)
                .getString("text");
        assertEquals(PassageText.format(out), readable);
        StringBuilder text = new StringBuilder();
        StringBuilder locations = new StringBuilder();
        int chars = 0;
        assertTrue(out.length() <= 3);
        for (int n = 0; n < out.length(); n++) {
          JSONObject p = out.getJSONObject(n);
          assertEquals("1706.03762.pdf", p.getString("filename"));
          chars += p.getString("text").length();
          locations
              .append("p")
              .append(p.getInt("page"))
              .append("c")
              .append(p.getInt("chunk"))
              .append(" ");
          text.append(p.getString("text")).append(' ');
        }
        assertTrue(chars <= 4800);
        System.out.println(test.getString("name") + ": " + locations);
        if (test.getBoolean("known_miss")) continue;
        String normalized = text.toString().toLowerCase(Locale.ROOT).replaceAll("\\s+", " ");
        JSONArray expected = test.getJSONArray("expected");
        for (int n = 0; n < expected.length(); n++)
          assertTrue(
              test.getString("name") + ": missing " + expected.getString(n) + " in " + locations,
              normalized.contains(expected.getString(n)));
      }
    } finally {
      context
          .getContentResolver()
          .releasePersistableUriPermission(Uri.parse(root), Intent.FLAG_GRANT_READ_URI_PERMISSION);
    }
  }
}
